                            .declarations
                            .class_parent(&owner)
                            .cloned()
                            .ok_or_else(|| {
                                self.error(
                                    "SPX-T231",
                                    format!(
                                        "`super.{method}` requires a parent; the enclosing class has none"
                                    ),
                                    *method_span,
                                )
