                            span: expr.span,
                            method_span: *method_span,
                            path,
                            method,
                            holder: holder.clone(),
                            callee,
                            args_len: args.len(),
                        });
                        if !args.is_empty() {
                            frames.push(Frame::MethodArgNext {
                                args,
                                index: 0,
                                bindings: bindings.clone(),
                                path,
                            });
