                            id: paths.at(path).expression_id(function),
                            ty,
                            ownership: OwnershipMode::Borrow,
                            kind: ResolvedExprKind::BorrowPlace {
                                operation: DeclarationId::new(op.id()),
                                place: place.clone(),
                            },
                            span,
                        });
