                            children,
                            index: index + 1,
                            bindings: bindings.clone(),
                            path,
                            segment,
                        });
                        frames.push(Frame::Enter {
                            expr: &children[index],
                            bindings,
                            path: paths.child(&frames, path, segment.at(index)),
