                Frame::MethodArgNext {
                    args,
                    index,
                    bindings,
                    path,
                } => {
                    if index < args.len() {
                        frames.push(Frame::MethodArgNext {
                            args,
                            index: index + 1,
                            bindings: bindings.clone(),
                            path,
                        });
                        frames.push(Frame::Enter {
                            expr: &args[index],
                            bindings,
                            path: paths.child(&frames, path, Seg::Arg.at(index + 1)),
