                    span,
                    path,
                    op,
                    right,
                    bindings,
                } => {
                    frames.push(Frame::FinishBinary { span, path, op });
                    frames.push(Frame::Enter {
                        expr: right,
                        bindings,
                        path: paths.child(&frames, path, Seg::Right),
                    });
