                Frame::BlockNext {
                    span,
                    path,
                    statements,
                    tail,
                    index,
                    scope,
                    resolved,
                } => {
                    if index == statements.len() {
                        frames.push(Frame::FinishBlock {
                            span,
                            path,
                            statements: resolved,
                        });
                        frames.push(Frame::Enter {
                            expr: tail,
                            bindings: scope,
                            path: paths.child(&frames, path, Seg::Tail),
                        });
