                                &mut paths,
                                span,
                                path,
                                statements,
                                tail,
                                index,
                                scope,
                                resolved,
                            ),
                            Statement::For {
                                item, values, body, ..
                            } => super::resolve_for::schedule(
                                self,
                                function,
                                &mut frames,
                                &mut paths,
                                span,
                                path,
                                statements,
                                tail,
                                index,
                                scope,
                                resolved,
                                item,
                                values,
                                body,
                                byte_ancestry.entry(),
