                        span,
                        path,
                        mode,
                        arms,
                        index: 0,
                        bindings,
                        scrutinee,
                        matched_type,
                        instance_arguments,
                        matched_kind,
                        resolved: Vec::with_capacity(arms.len()),
                    });
