                            expr: &arm.value,
                            bindings: arm_bindings,
                            path: paths.child(&frames, path, edge.then(Seg::Value)),
                        });
                    }
                }
                Frame::ScalarMatchAfterArm {
                    span,
                    path,
                    mode,
                    arms,
                    index,
                    bindings,
                    scrutinee,
                    mut resolved,
                    pattern,
                } => {
