                        .declarations
                        .record_fields(owner)
                        .and_then(|fields| fields.iter().find(|item| item.id == field_id))
                        .map(|item| item.ty.clone())
                        .ok_or_else(|| {
                            self.error(
                                "SPX-H001",
                                format!("field `{field_id}` has no resolved type"),
                                span,
                            )
