                    path,
                    type_name,
                    record,
                    arguments,
                    fields,
                    index,
                    bindings,
                    mut resolved,
                    field,
                } => {
                    let value = results.pop().expect("record field result retained");
                    resolved.push(ResolvedFieldInitializer { field, value });
                    frames.push(Frame::RecordNext {
                        span,
                        path,
                        type_name,
                        record,
                        arguments,
                        fields,
                        index: index + 1,
                        bindings,
                        resolved,
                    });
                }
                Frame::VariantNext {
                    span,
                    path,
                    type_name,
                    case_name,
                    variant,
                    case,
                    type_arguments,
                    fields,
                    index,
                    bindings,
                    resolved,
                } => {
                    if index == fields.len() {
                        let arguments = type_arguments
                            .iter()
                            .map(|argument| {
                                self.resolve_call_type_argument(function, argument, span)
                            })
                            .collect::<Result<Vec<_>, _>>()?;
