                    span,
                    path,
                    type_name,
                    case_name,
                    variant,
                    case,
                    type_arguments,
                    fields,
                    index,
                    bindings,
                    mut resolved,
                    field,
                } => {
                    let value = results.pop().expect("variant field result retained");
                    resolved.push(ResolvedFieldInitializer { field, value });
                    frames.push(Frame::VariantNext {
                        span,
                        path,
                        type_name,
                        case_name,
                        variant,
                        case,
                        type_arguments,
                        fields,
                        index: index + 1,
                        bindings,
                        resolved,
                    });
