                            matches!(kind, DeclarationKind::Record | DeclarationKind::Variant)
                        })
                        .ok_or_else(|| {
                            self.error(
                                "SPX-H001",
                                "cannot resolve match on a non-record/non-variant value",
                                span,
                            )
