                            span,
                            path,
                            mode,
                            arms,
                            index,
                            bindings,
                            scrutinee,
                            matched_type,
                            instance_arguments,
                            matched_kind,
                            resolved,
                            pattern,
                        });
                        let edge = Seg::Arm.at(index);
                        frames.push(Frame::Enter {
                            expr: &arm.value,
                            bindings: arm_bindings.clone(),
                            path: paths.child(&frames, path, edge.then(Seg::Value)),
