                                let edge = Seg::Arm.at(index).then(Seg::Binding);
                                let binding = ResolvedBinding {
                                    id: paths.at(path).value_local_with(function, &[edge]),
                                    name: name.clone(),
                                    ownership: OwnershipMode::Value,
                                    ty: scrutinee.ty.clone(),
                                    span: arm.pattern.span(),
                                };
