                        if let Some(guard) = &arm.guard {
                            frames.push(Frame::Enter {
                                expr: guard.as_ref(),
                                bindings: arm_bindings.clone(),
                                path: paths.child(&frames, path, edge.then(Seg::Guard)),
                            });
                        }
