                        .declarations
                        .field_id(owner, field)
                        .cloned()
                        .ok_or_else(|| {
                            self.error(
                                "SPX-H001",
                                format!("unresolved field `{field}` on `{owner}`"),
                                span,
                            )
                        })?;
