            id: ValueId::local(function, statement_path),
            name: profile.wrapper.to_owned(),
            ownership: OwnershipMode::Value,
            ty: ResolvedType::Usize,
            span,
        },
        mutable: false,
        value: lowered,
        span,
    }
}

