//! Canonical lowering for bounded `for item in values` Vec traversal.
use crate::hir::resolver_scope::Scope;

pub(super) mod bytes;
pub(super) mod record;

use crate::ast::{BinaryOp, Span};
use std::collections::BTreeMap;
use std::rc::Rc;

