                ExprKind::LexicalExit { kind, value } => {
                    if let Some(value) = value {
                        if *kind != crate::ast::LexicalExitKind::Return
                            || !crate::hir::lexical_exit::return_operand::source_named_handoff(
                                value,
                            )
                        {
                            pending.push(Item::Expression(value));
                        }
                    }
                }
                ExprKind::Closure { .. } => {}

                ExprKind::Int(_)
                | ExprKind::Int32(_)
                | ExprKind::Char(_)
                | ExprKind::Uint8(_)
                | ExprKind::Usize(_)
                | ExprKind::Float32(_)
                | ExprKind::Float64(_)
                | ExprKind::Bool(_)
                | ExprKind::Var(_) => {}
